\documentclass{article}
\usepackage{graphicx}
\usepackage{subcaption}
\begin{document}
\begin{figure}
\begin{subfigure}{0.45\textwidth}
\includegraphics[width=\textwidth]{antes.png}
\caption{Antes}\label{fig:antes}
\end{subfigure}
\begin{subfigure}{0.45\textwidth}
\includegraphics[width=\textwidth]{despues.png}
\caption{Después}\label{fig:despues}
\end{subfigure}
\caption{Comparación del crecimiento}\label{fig:comparacion}
\end{figure}
Los paneles \ref{fig:antes} y \ref{fig:despues} muestran el cambio.
\end{document}
